    ('Kit.lua', '0x2013, 0x2014,', '0x2013, 0x2013,', 'the em dash left out of Barlow'),
    ('Kit.lua', '        if cp < BARLOW[mid * 2 - 1] then', '        if cp <= BARLOW[mid * 2 - 1] then', 'a range start counted outside it'),
    ('Kit.lua', '        elseif cp > BARLOW[mid * 2] then', '        elseif cp >= BARLOW[mid * 2] then', 'a range end counted outside it'),
    ('Kit.lua', '                cp = cp * 64 + (c - 0x80)', '                cp = cp * 64 + c', 'continuation bytes decoded wrong'),
    ('Kit.lua', '                if not c or c < 0x80 or c > 0xBF then return true end', '                if not c then return true end', 'a broken sequence read as a character'),
