def run_tests(root):
    for test in sorted(glob.glob(os.path.join(root, 'tests', 'test_*.lua'))):
        # A mutant can loop a test forever (MINOR 51's results list appending to itself did), and a
        # test that never ends has failed, so it counts as caught rather than stalling the run.
        try:
            if subprocess.run([LUA, test], capture_output=True, timeout=TEST_TIMEOUT).returncode != 0:
                return False
        except subprocess.TimeoutExpired:
            return False
    return True


def main():
    work = tempfile.mkdtemp(prefix='eui-mutate-')
    caught, bad = 0, []
    try:
        lib = os.path.join(work, 'lib')
        if not run_tests(ROOT):
            print('the unmutated tests fail - fix them first')
            return 1
        for rel, old, new, label in MUTANTS:
            if os.path.exists(lib):
                shutil.rmtree(lib)
            shutil.copytree(ROOT, lib, ignore=shutil.ignore_patterns('.git', '__pycache__'))
            path = os.path.join(lib, rel)
            with open(path, encoding='utf-8', newline='') as f:
                text = f.read()
            n = text.count(old)
            if n != 1:
                bad.append('ANCHOR x%d  %s' % (n, label))
                continue
            with open(path, 'w', encoding='utf-8', newline='') as f:
                f.write(text.replace(old, new))
            if run_tests(lib):
                bad.append('SURVIVED  %s' % label)
            else:
                caught += 1
    finally:
        shutil.rmtree(work, ignore_errors=True)
    for line in bad:
        print(line)
    print('%d of %d mutants caught' % (caught, len(MUTANTS)))
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
